from itertools import permutations

# Generate all possible permutations of columns for 21 queens
solutions = list(permutations(range(21), 21))

# Check each permutation for validity (no two queens attack each other)
for solution in solutions:
    valid = True
    for i in range(21):
        for j in range(i + 1, 21):
            if solution[i] == solution[j] or abs(solution[i] - solution[j]) == abs(i - j):
                valid = False
                break
        if not valid:
            break
    if valid:
        print(solution)
        break
